const SOURCES = [
  ['data/usage.jsonl', '稳定性、响应速度、缓存与成本'],
  ['config.json · context / rounds', '上下文配置'],
  ['workspace/handoffs/*.md', '交接健康'],
  ['workspace/memory/*.jsonl', '记忆健康、行为侧写（E/I、S/N、T/F、J/P）'],
];

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined) n.textContent = text;
  return n;
}

function fmtTime(ms, lang) {
  if (!ms) return '—';
  const d = new Date(ms);
  const p = (n) => String(n).padStart(2, '0');
  return lang === 'zh'
    ? `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`
    : d.toISOString().slice(0, 16).replace('T', ' ');
}

function scoreClass(state) {
  return `sc-score sc-${state || 'unknown'}`;
}

/* ------------------------------------------------------------------ 硬件 */

/**
 * 一条极小折线。稀疏序列里 null 是断点——断开，不假装连上。
 * 只画走势，不标刻度；值在旁边用文字给，图上不叠数字。
 */
function sparkline(points, { w = 108, h = 26, state = 'ok' } = {}) {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  svg.setAttribute('class', 'sc-spark');
  svg.setAttribute('preserveAspectRatio', 'none');
  svg.dataset.state = state;

  const pad = 3;
  const inner = w - pad * 2;
  const n = points.length;
  const step = n > 1 ? inner / (n - 1) : 0;
  const y = (v) => pad + (1 - Math.max(0, Math.min(100, v)) / 100) * (h - pad * 2);
  const x = (i) => pad + i * step;

  // 一条很淡的 50 分基准线，给个参照
  const mid = document.createElementNS(NS, 'line');
  mid.setAttribute('x1', String(pad));
  mid.setAttribute('x2', String(w - pad));
  mid.setAttribute('y1', String(y(50)));
  mid.setAttribute('y2', String(y(50)));
  mid.setAttribute('class', 'sc-spark-mid');
  svg.append(mid);

  // 分段画：遇到 null 就断开
  let seg = [];
  const flush = () => {
    if (seg.length === 1) {
      const dot = document.createElementNS(NS, 'circle');
      dot.setAttribute('cx', String(seg[0].x));
      dot.setAttribute('cy', String(seg[0].y));
      dot.setAttribute('r', '1.6');
      dot.setAttribute('class', 'sc-spark-line');
      svg.append(dot);
    } else if (seg.length > 1) {
      const pl = document.createElementNS(NS, 'polyline');
      pl.setAttribute('points', seg.map((p) => `${p.x},${p.y}`).join(' '));
      pl.setAttribute('class', 'sc-spark-line');
      svg.append(pl);
    }
    seg = [];
  };

  points.forEach((p, i) => {
    if (Number.isFinite(p)) seg.push({ x: x(i), y: y(p) });
    else flush();
  });
  flush();

  // 最后一个点给一个实心点，表示「现在」
  const lastIdx = points.reduce((acc, p, i) => (Number.isFinite(p) ? i : acc), -1);
  if (lastIdx >= 0) {
    const dot = document.createElementNS(NS, 'circle');
    dot.setAttribute('cx', String(x(lastIdx)));
    dot.setAttribute('cy', String(y(points[lastIdx])));
    dot.setAttribute('r', '2.4');
    dot.setAttribute('class', 'sc-spark-dot');
    svg.append(dot);
  }
  return svg;
}

/**
 * 趋势文案在客户端算。
 * 理由：服务端 src/*.mjs 随 Coo 启动加载，改完要重启整个 Coo 才生效；
 * 面板脚本是静态资源，改完刷新页面就能看到。同一套措辞写在这里，改文案不用重启。
 * 服务端仍会给 d.trend（纯文本报告用），这里优先自己算。
 */
function trendText(d, lang) {
  const delta = d.delta;
  if (!Number.isFinite(delta)) return null;
  const zh = !String(lang || 'zh').toLowerCase().startsWith('en');
  const abs = Math.round(Math.abs(delta));
  if (abs < 5) return null;                       // 5 分以内是风噪，不写
  const weak = d.state === 'bad' || d.state === 'warn';
  if (delta > 0) {
    // 41 分的维度写「高 32 分」会让人以为没事，得说「回升」——回升了也还是吃力。
    return weak
      ? (zh ? `近几天在回升 +${abs}` : `recovering +${abs}`)
      : (zh ? `比之前高 ${abs} 分` : `+${abs} vs earlier`);
  }
  return zh ? `比之前低 ${abs} 分` : `-${abs} vs earlier`;
}

/**
 * 环形总分。比一个裸数字多一点「仪表」的实感：
 * 圆弧的缺口就是丢掉的分数，一眼能看出还剩多少。
 */
function scoreRing(value, tone) {
  const NS = 'http://www.w3.org/2000/svg';
  const size = 132;
  const stroke = 10;
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const v = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
  svg.setAttribute('class', `sc-ring sc-ring-${tone || 'muted'}`);

  const track = document.createElementNS(NS, 'circle');
  track.setAttribute('cx', String(size / 2));
  track.setAttribute('cy', String(size / 2));
  track.setAttribute('r', String(r));
  track.setAttribute('class', 'sc-ring-track');
  track.setAttribute('stroke-width', String(stroke));
  svg.append(track);

  const arc = document.createElementNS(NS, 'circle');
  arc.setAttribute('cx', String(size / 2));
  arc.setAttribute('cy', String(size / 2));
  arc.setAttribute('r', String(r));
  arc.setAttribute('class', 'sc-ring-arc');
  arc.setAttribute('stroke-width', String(stroke));
  arc.setAttribute('stroke-dasharray', `${(c * v) / 100} ${c}`);
  arc.setAttribute('stroke-linecap', 'round');
  // 从 12 点开始顺时针
  arc.setAttribute('transform', `rotate(-90 ${size / 2} ${size / 2})`);
  svg.append(arc);

  const text = document.createElementNS(NS, 'text');
  text.setAttribute('x', String(size / 2));
  text.setAttribute('y', String(size / 2 + 2));
  text.setAttribute('text-anchor', 'middle');
  text.setAttribute('dominant-baseline', 'middle');
  text.setAttribute('class', 'sc-ring-num');
  text.textContent = Number.isFinite(value) ? String(value) : '—';
  svg.append(text);

  const unit = document.createElementNS(NS, 'text');
  unit.setAttribute('x', String(size / 2));
  unit.setAttribute('y', String(size / 2 + 24));
  unit.setAttribute('text-anchor', 'middle');
  unit.setAttribute('class', 'sc-ring-unit');
  unit.textContent = '/100';
  svg.append(unit);

  return svg;
}

/**
 * 六维横条。雷达看形状，横条看排序——两个一起才像体检表而不像装饰。
 * 每行都能直接点开对应维度，不用滚下去找。
 */
function hwBars(dimensions, t) {
  const wrap = el('div', 'sc-hw-bars');
  const max = 100;
  for (const d of dimensions) {
    const row = el('div', 'sc-hw-bar-row');
    row.dataset.state = d.state;

    const name = el('span', 'sc-hw-bar-name', d.title);
    row.append(name);

    const track = el('span', 'sc-hw-bar-track');
    const fill = el('span', 'sc-hw-bar-fill');
    fill.style.width = `${Number.isFinite(d.score) ? Math.max(2, Math.min(100, d.score)) : 0}%`;
    track.append(fill);
    // 60 分处画一条极淡的基准：及格线
    const mark = el('span', 'sc-hw-bar-mark');
    mark.style.left = `${(60 / max) * 100}%`;
    track.append(mark);
    row.append(track);

    const val = el('span', 'sc-hw-bar-val', d.metricValue ?? (Number.isFinite(d.score) ? String(d.score) : '—'));
    row.append(val);

    const delta = Number.isFinite(d.delta) && Math.abs(d.delta) >= 5 ? d.delta : null;
    const arrow = el('span', 'sc-hw-bar-delta', delta === null ? '' : `${delta > 0 ? '↑' : '↓'}${Math.round(Math.abs(delta))}`);
    if (delta !== null) arrow.dataset.dir = delta > 0 ? 'up' : 'down';
    row.append(arrow);

    wrap.append(row);
  }
  return wrap;
}

/** 顶部状态条：六个小格，一眼看完谁好谁差。 */
function hwTiles(dimensions, t) {
  const wrap = el('div', 'sc-hw-tiles');
  for (const d of dimensions) {
    const tile = el('div', 'sc-hw-tile');
    tile.dataset.state = d.state;
    tile.append(el('span', 'sc-hw-tile-name', d.title));
    tile.append(el('span', 'sc-hw-tile-score', Number.isFinite(d.score) ? String(d.score) : '—'));
    // 一条极细的底条，给「高低」一个形状，不用读数字
    const track = el('span', 'sc-hw-tile-track');
    const fill = el('span', 'sc-hw-tile-fill');
    fill.style.width = `${Number.isFinite(d.score) ? Math.max(3, Math.min(100, d.score)) : 0}%`;
    track.append(fill);
    tile.append(track);
    wrap.append(tile);
  }
  return wrap;
}

/**
 * 逐日柱：比折线更能看出「哪一天塌了」。
 * 只给有逐日序列的维度用（稳定性/速度/缓存有，配置类没有）。
 */
function dailyBars(series) {
  const pts = (series || []).filter((p) => Number.isFinite(p.score));
  if (pts.length < 2) return null;
  const wrap = el('div', 'sc-bars');
  const maxN = pts.reduce((m, p) => Math.max(m, p.n || 0), 0) || 1;
  for (const p of pts) {
    const cell = el('div', 'sc-bar-cell');
    const v = Math.max(0, Math.min(100, p.score));
    cell.dataset.state = v >= 78 ? 'ok' : v >= 60 ? 'warn' : 'bad';
    cell.title = `${p.day} · ${Math.round(p.score)} · n=${p.n}`;

    const track = el('div', 'sc-bar-track');
    // 样本量先画：柱越高说明那天调用越多，压低在背景
    const volume = el('div', 'sc-bar-volume');
    volume.style.height = `${Math.max(2, ((p.n || 0) / maxN) * 100)}%`;
    track.append(volume);
    const fill = el('div', 'sc-bar-fill');
    fill.style.height = `${Math.max(3, v)}%`;
    track.append(fill);
    cell.append(track);

    cell.append(el('div', 'sc-bar-val', String(Math.round(p.score))));
    // 日期可能是 2026-11-17，也可能已经是 11-17；统一取末 5 位
    cell.append(el('div', 'sc-bar-day', String(p.day || '').slice(-5)));
    wrap.append(cell);
  }
  return wrap;
}
function dimRow(d, t, lang) {
  const row = el('details', 'sc-dim');
  row.dataset.state = d.state;

  const sum = el('summary', 'sc-dim-sum');
  sum.append(el('span', 'sc-dim-title', d.title));

  const scoreBox = el('span', 'sc-dim-score');
  scoreBox.append(el('span', scoreClass(d.state), Number.isFinite(d.score) ? String(d.score) : '—'));
  sum.append(scoreBox);

  const pts = (d.series || []).map((p) => (Number.isFinite(p.score) ? p.score : null));
  if (pts.filter((v) => v !== null).length >= 2) {
    sum.append(sparkline(pts, { state: d.state }));
  } else if (!d.hideTrend) {
    const label = lang === 'zh' ? (pts.length ? '趋势样本不足' : '暂无逐日趋势') : (pts.length ? 'Too few trend samples' : 'No daily trend');
    sum.append(el('span', 'sc-profile-period sc-no-trend', label));
  }

  // 趋势放在折线后面：先看形状，再看数字。
  const trendStr = trendText(d, lang) ?? d.trend ?? null;
  if (trendStr) {
    const trend = el('span', 'sc-trend', trendStr);
    trend.dataset.dir = Number.isFinite(d.delta) ? (d.delta > 0 ? 'up' : 'down') : 'flat';
    sum.append(trend);
  }
  row.append(sum);

  row.append(el('div', 'sc-dim-head', d.headline));

  // 有逐日序列的维度，展开后先给柱状图：哪天塌了一眼能看出来。
  const bars = dailyBars(d.series);
  if (bars) {
    const chartBox = el('div', 'sc-dim-chart');
    chartBox.append(bars);
    row.append(chartBox);
  }

  const body = el('div', 'sc-dim-body');
  body.append(el('div', 'sc-label', t.evidence));
  const table = el('div', 'sc-ev');
  for (const e of d.evidence || []) {
    const line = el('div', 'sc-ev-row');
    line.append(el('span', 'sc-ev-k', e.label));
    line.append(el('span', 'sc-ev-v', String(e.value)));
    if (e.hint) line.append(el('span', 'sc-ev-h', e.hint));
    table.append(line);
  }
  body.append(table);
  body.append(el('div', 'sc-label', t.formula));
  body.append(el('div', 'sc-prose', d.formula));
  body.append(el('div', 'sc-label', t.meaning));
  body.append(el('div', 'sc-prose', d.meaning));
  row.append(body);
  return row;
}

function hardwareRadar(dimensions) {
  const size = 260;
  const cx = size / 2;
  const cy = size / 2;
  const r = 88;
  const labels = ['稳定', '速度', '缓存', '上下文', '交接', '记忆'];
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
  svg.setAttribute('class', 'sc-hw-radar');
  const point = (value, radius = r) => {
    const v = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
    const i = point.i;
    const angle = -Math.PI / 2 + (i * Math.PI * 2) / 6;
    const rr = radius * v / 100;
    return `${cx + Math.cos(angle) * rr},${cy + Math.sin(angle) * rr}`;
  };
  for (const frac of [0.25, 0.5, 0.75, 1]) {
    const poly = document.createElementNS(NS, 'polygon');
    poly.setAttribute('points', labels.map((_, i) => { point.i = i; return point(frac * 100); }).join(' '));
    poly.setAttribute('class', 'sc-hw-grid');
    svg.append(poly);
  }
  for (let i = 0; i < 6; i += 1) {
    const angle = -Math.PI / 2 + (i * Math.PI * 2) / 6;
    const line = document.createElementNS(NS, 'line');
    line.setAttribute('x1', String(cx)); line.setAttribute('y1', String(cy));
    line.setAttribute('x2', String(cx + Math.cos(angle) * r));
    line.setAttribute('y2', String(cy + Math.sin(angle) * r));
    line.setAttribute('class', 'sc-hw-axis');
    svg.append(line);
  }
  const values = dimensions.map((d) => d.score);
  const poly = document.createElementNS(NS, 'polygon');
  poly.setAttribute('points', values.map((v, i) => { point.i = i; return point(v); }).join(' '));
  poly.setAttribute('class', 'sc-hw-shape');
  svg.append(poly);
  values.forEach((v, i) => {
    if (!Number.isFinite(v)) return;
    point.i = i;
    const [x, y] = point(v).split(',');
    const dot = document.createElementNS(NS, 'circle');
    dot.setAttribute('cx', x); dot.setAttribute('cy', y); dot.setAttribute('r', '3.2');
    dot.setAttribute('class', 'sc-hw-dot'); svg.append(dot);
  });
  labels.forEach((label, i) => {
    const angle = -Math.PI / 2 + (i * Math.PI * 2) / 6;
    const txt = document.createElementNS(NS, 'text');
    txt.setAttribute('x', String(cx + Math.cos(angle) * (r + 21)));
    txt.setAttribute('y', String(cy + Math.sin(angle) * (r + 21)));
    txt.setAttribute('text-anchor', 'middle'); txt.setAttribute('class', 'sc-hw-label'); txt.textContent = label; svg.append(txt);
  });
  return svg;
}

function hardwareRadarLegend(t) {
  const box = el('div', 'sc-hw-radar-copy');
  box.append(el('div', 'sc-sect-title', t.hardwareChartTitle));
  box.append(el('div', 'sc-prose', t.hardwareChartNote));
  return box;
}
function renderHardware(ctx, report, actions) {
  const t = T[ctx.lang];
  const hw = report.hardware;
  const sum = report.summary || {};
  const dims = hw.dimensions || [];
  const root = el('div', 'sc-root');

  /* ---- 首屏：结论 + 环 + 小格。这一屏决定这页是「病历」还是「仪表盘」。 ---- */
  const hero = el('div', `sc-hero sc-hero-${sum.tone || 'muted'}`);

  const heroHead = el('div', 'sc-hero-head');
  const ringBox = el('div', 'sc-ring-box');
  ringBox.append(scoreRing(hw.overall, sum.tone || 'muted'));
  heroHead.append(ringBox);

  const stateBlock = el('div', 'sc-hero-state-block');
  stateBlock.append(el('div', 'sc-hero-state', sum.stateWord || hw.level || t.unknown));
  if (sum.sentence) stateBlock.append(el('p', 'sc-hero-line', sum.sentence));

  const heroActions = el('div', 'sc-head-actions');
  const refresh = el('button', 'sc-btn', t.refresh);
  refresh.addEventListener('click', () => void actions.refresh(), { signal: ctx.signal });
  const copy = el('button', 'sc-btn sc-btn-ghost', t.copy);
  copy.addEventListener('click', () => void copyReport(ctx, copy, t), { signal: ctx.signal });
  heroActions.append(refresh, copy);
  stateBlock.append(heroActions);
  heroHead.append(stateBlock);
  hero.append(heroHead);

  if (sum.detail) hero.append(el('p', 'sc-hero-detail', sum.detail));
  if (hw.overall === null) hero.append(el('p', 'sc-hero-detail', t.noOverall));

  // 六个小格：一眼看完谁好谁差，不用滚。
  if (dims.length) hero.append(hwTiles(dims, t));

  const meta = el('div', 'sc-hero-meta');
  meta.append(el('span', '', `${hw.scoredCount ?? 0}/6 ${t.dims}`));
  meta.append(el('span', 'sc-sep', '·'));
  meta.append(el('span', '', `${fmtTime(report.collectedAt, ctx.lang)} · ${report.sampleDays}d`));
  if (hw.unknownCount > 0) {
    meta.append(el('span', 'sc-sep', '·'));
    meta.append(el('span', '', t.unknownDims(hw.unknownCount)));
  }
  hero.append(meta);
  root.append(hero);

  /* ---- 形状 + 排序：雷达看轮廓，横条看谁拖后腿 ---- */
  const chart = el('div', 'sc-hw-chart');
  const chartLeft = el('div', 'sc-hw-chart-left');
  chartLeft.append(hardwareRadar(dims));
  const chartRight = el('div', 'sc-hw-chart-right');
  chartRight.append(hardwareRadarLegend(t));
  if (dims.length) chartRight.append(hwBars(dims, t));
  chart.append(chartLeft, chartRight);
  root.append(chart);

  /* ---- 旧存档没有 summary 字段：退回平铺六维，不白屏 ---- */
  if (!sum.top && !sum.rest) {
    const box = el('div', 'sc-dims');
    for (const d of dims) box.append(dimRow(d, t, ctx.lang));
    root.append(box);
    if (report.problems?.length) {
      const pbox = el('div', 'sc-problems');
      pbox.append(el('div', 'sc-label', t.readProblems));
      for (const p of report.problems) pbox.append(el('div', 'sc-prose', p));
      root.append(pbox);
    }
    root.append(el('div', 'sc-footer', t.footer));
    return root;
  }

  /* ---- 六项全部展开：排序后逐项读证据 ---- */
  const allScored = [...(sum.top || []), ...(sum.rest || [])];
  if (allScored.length) {
    const sect = el('div', 'sc-sect');
    const head = el('div', 'sc-sect-head');
    head.append(el('span', 'sc-sect-title', t.allDimensions));
    head.append(el('span', 'sc-sect-note', t.allDimensionsNote));
    sect.append(head);
    const box = el('div', 'sc-dims');
    for (const d of allScored) box.append(dimRow(d, t, ctx.lang));
    sect.append(box);
    root.append(sect);
  }

  if (sum.unknown?.length) {
    const box = el('div', 'sc-dims sc-dims-rest');
    for (const d of sum.unknown) box.append(dimRow(d, t, ctx.lang));
    root.append(box);
  }

  /* ---- 你可以做的：陪伴产品不能只判分不给路 ---- */
  if (sum.care?.length) {
    const sect = el('div', 'sc-care');
    sect.append(el('div', 'sc-sect-title', t.careTitle));
    for (const c of sum.care) {
      const line = el('div', 'sc-care-row');
      line.append(el('span', 'sc-care-k', c.title));
      line.append(el('span', 'sc-care-v', c.body));
      sect.append(line);
    }
    root.append(sect);
  }

  if (report.problems?.length) {
    const box = el('div', 'sc-problems');
    box.append(el('div', 'sc-label', t.readProblems));
    for (const p of report.problems) box.append(el('div', 'sc-prose', p));
    root.append(box);
  }
  root.append(el('div', 'sc-footer', t.footer));
  return root;
}

/* ------------------------------------------------------------------ 人格 */

function radar(axes, t) {
  const size = 220;
  const cx = size / 2;
  const cy = size / 2;
  const r = size / 2 - 34;
  const labels = [
    ['E', 'I', 'EI'],
    ['S', 'N', 'SN'],
    ['T', 'F', 'TF'],
    ['J', 'P', 'JP'],
  ];
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
  svg.setAttribute('class', 'sc-radar');

  for (const frac of [0.25, 0.5, 0.75, 1]) {
    const poly = document.createElementNS(NS, 'polygon');
    const pts = [];
    for (let i = 0; i < 4; i += 1) {
      const ang = -Math.PI / 2 + (i * Math.PI) / 2;
      pts.push(`${cx + Math.cos(ang) * r * frac},${cy + Math.sin(ang) * r * frac}`);
    }
    poly.setAttribute('points', pts.join(' '));
    poly.setAttribute('class', 'sc-radar-grid');
    svg.append(poly);
  }
  for (let i = 0; i < 4; i += 1) {
    const ang = -Math.PI / 2 + (i * Math.PI) / 2;
    const line = document.createElementNS(NS, 'line');
    line.setAttribute('x1', String(cx));
    line.setAttribute('y1', String(cy));
    line.setAttribute('x2', String(cx + Math.cos(ang) * r));
    line.setAttribute('y2', String(cy + Math.sin(ang) * r));
    line.setAttribute('class', 'sc-radar-axis');
    svg.append(line);
  }

  const draw = (values, cls) => {
    const pts = [];
    for (let i = 0; i < 4; i += 1) {
      const v = Number.isFinite(values?.[labels[i][2]]) ? values[labels[i][2]] : 0;
      const ang = -Math.PI / 2 + (i * Math.PI) / 2;
      const rr = (r * Math.max(0, Math.min(100, v))) / 100;
      pts.push(`${cx + Math.cos(ang) * rr},${cy + Math.sin(ang) * rr}`);
    }
    const poly = document.createElementNS(NS, 'polygon');
    poly.setAttribute('points', pts.join(' '));
    poly.setAttribute('class', cls);
    svg.append(poly);
  };
  draw(axes.self, 'sc-radar-self');
  draw(axes.behavior, 'sc-radar-behav');

  for (let i = 0; i < 4; i += 1) {
    const ang = -Math.PI / 2 + (i * Math.PI) / 2;
    const x = cx + Math.cos(ang) * (r + 18);
    const y = cy + Math.sin(ang) * (r + 16);
    const txt = document.createElementNS(NS, 'text');
    txt.setAttribute('x', String(x));
    txt.setAttribute('y', String(y));
    txt.setAttribute('text-anchor', 'middle');
    txt.setAttribute('class', 'sc-radar-label');
    txt.textContent = `${labels[i][0]}/${labels[i][1]}`;
    svg.append(txt);
  }
  return svg;
}

function axisRows(self, behav, t) {
  const pairs = [
    ['EI', 'E', 'I'],
    ['SN', 'S', 'N'],
    ['TF', 'T', 'F'],
    ['JP', 'J', 'P'],
  ];
  const wrap = el('div', 'sc-axes');
  for (const [id, hi, lo] of pairs) {
    const s = Number.isFinite(self?.[id]) ? self[id] : null;
    const b = Number.isFinite(behav?.[id]) ? behav[id] : null;
    const row = el('div', 'sc-axis');
    row.append(el('span', 'sc-axis-name', `${hi}/${lo}`));
    const track = el('span', 'sc-axis-track');
    if (s !== null) {
      const dot = el('span', 'sc-axis-dot sc-axis-self');
      dot.style.left = `${s}%`;
      track.append(dot);
    }
    if (b !== null) {
      const dot = el('span', 'sc-axis-dot sc-axis-behav');
      dot.style.left = `${b}%`;
      track.append(dot);
    }
    track.append(el('span', 'sc-axis-mid'));
    row.append(track);
    const vals = el('span', 'sc-axis-vals');
    vals.append(el('span', 'sc-axis-self-v', s === null ? '?' : String(Math.round(s))));
    vals.append(el('span', 'sc-axis-sep', '/'));
    vals.append(el('span', 'sc-axis-behav-v', b === null ? '?' : String(Math.round(b))));
    row.append(vals);
    wrap.append(row);
  }
  return wrap;
}

function creativeCard(ctx, p, t, actions) {
  const card = el('div', 'sc-creative');
  card.append(el('div', 'sc-sect-title', t.creativeTitle));
  if (p.creative?.taken) {
    card.append(el('div', 'sc-creative-blurb', p.creative.blurb || ''));
    if (p.creative.tags?.length) {
      const tags = el('div', 'sc-creative-tags');
      for (const tag of p.creative.tags) tags.append(el('span', 'sc-creative-tag', tag));
      card.append(tags);
    }
  } else {
    card.append(el('div', 'sc-creative-blurb', t.creativeEmpty));
  }
  card.append(el('div', 'sc-note', t.creativeHint));
  if (!p.creative?.taken) {
    const controls = el('div', 'sc-head-actions');
    const btn = el('button', 'sc-btn', t.creativeStart);
    const reload = el('button', 'sc-btn sc-btn-ghost', t.creativeReload);
    const status = el('div', 'sc-head-note', '');
    status.setAttribute('role', 'status');
    reload.addEventListener('click', () => void actions.load(), { signal: ctx.signal });
    btn.addEventListener('click', async () => {
      if (btn.disabled) return;
      btn.disabled = true;
      status.textContent = t.starting;
      try {
        const res = await ctx.invoke('startCreative');
        if (res?.ok) status.textContent = t.creativeQueued;
        else if (res?.error === 'already-requested') status.textContent = t.creativePending;
        else if (res?.error === 'taken-recently') status.textContent = t.takenRecently;
        else if (res?.error === 'quiz-disabled') status.textContent = t.quizOff;
        else status.textContent = String(res?.error ?? t.failed);
      } catch (err) {
        status.textContent = err?.message ?? t.failed;
      } finally {
        btn.disabled = false;
      }
    }, { signal: ctx.signal });
    controls.append(btn, reload);
    card.append(controls, status);
  }
  return card;
}

/* ---- 标签：首屏的主菜。抽卡感（稀有度）+ 外号感（口语判词）各占一半 ---- */

const TIER_ORDER = [4, 3, 2, 1];

const PERSONALITY_PORTRAITS = {
  sleepy: { src: 'data:image/png;base64,', alt: '困困打哈欠的蓝发小鱼女孩' },
  happy: { src: 'data:image/png;base64,', alt: '开心回应的蓝发小鱼女孩' },
  curious: { src: 'data:image/png;base64,', alt: '好奇探头的蓝发小鱼女孩' },
  shy: { src: 'data:image/png;base64,', alt: '害羞捧脸的蓝发小鱼女孩' },
};

function personalityPortraitState(tags) {
  const nickname = String(tags?.nickname ?? '');
  const direct = [
    ['sleepy', /省电|全天小鱼|全天都在|夜行|深夜|凌晨/],
    ['happy', /开心|高兴|活泼|话匣子|总先开口/],
    ['curious', /好奇|探头|联想|反问|发问/],
    ['shy', /害羞|慢热|躲躲|憋着|咽回去|不出声/],
  ];
  for (const [state, pattern] of direct) {
    if (pattern.test(nickname)) return state;
  }

  const tagIds = new Set((tags?.tags ?? []).map((tag) => tag.id));
  const copy = `${nickname} ${(tags?.tags ?? []).map((tag) => `${tag.label ?? ''} ${tag.roast ?? ''}`).join(' ')} ${(tags?.combos ?? []).map((combo) => `${combo.title ?? ''} ${combo.blurb ?? ''}`).join(' ')}`;
  if (/省电|全天都在|夜里才活|凌晨三点还在/.test(copy) || ['cache-ace', 'all-day', 'night-owl', 'deep-night'].some((id) => tagIds.has(id))) return 'sleepy';
  if (/开心|高兴|话匣子|总先开口/.test(copy) || ['talky', 'high-speak'].some((id) => tagIds.has(id))) return 'happy';
  if (/好奇|探头|能拐三个弯|说完会递回来/.test(copy) || ['long-query', 'asks-back'].some((id) => tagIds.has(id))) return 'curious';
  if (/害羞|慢热|话到嘴边又咽回去|多数时候不出声|陪着不说话/.test(copy) || ['silent-blocked', 'low-speak', 'quiet-but-there'].some((id) => tagIds.has(id))) return 'shy';
  return 'happy';
}

function personalityPortrait(tags) {
  const state = personalityPortraitState(tags);
  const portrait = PERSONALITY_PORTRAITS[state];
  const image = el('img', 'sc-nick-avatar');
  image.setAttribute('src', portrait.src);
  image.setAttribute('alt', portrait.alt);
  image.setAttribute('data-personality-state', state);
  image.setAttribute('decoding', 'async');
  return image;
}

function tierClass(tier) {
  return `sc-tier-${tier}`;
}

/** 稀有度条：只看同池命中数，不编全网百分比。 */
function rarityStrip(tags, t) {
  const box = el('div', 'sc-rarity');
  const total = tags.hitCount || 0;
  box.append(el('span', 'sc-rarity-pool', t.rarityPool(tags.pool, total)));
  const chips = el('div', 'sc-rarity-chips');
  for (const tier of TIER_ORDER) {
    const n = tags.rarity?.[tier] ?? 0;
    if (n === 0) continue;
    const chip = el('span', `sc-rarity-chip ${tierClass(tier)}`);
    chip.append(el('span', 'sc-rarity-n', String(n)));
    chip.append(el('span', 'sc-rarity-k', t.tiers[tier]));
    chips.append(chip);
  }
  box.append(chips);
  return box;
}

/** 单张标签卡。证据在前、判词在后——先给「凭什么」，再给「像不像你」。 */
function tagCard(tag) {
  const card = el('div', `sc-tag ${tierClass(tag.tier)}`);
  card.append(el('span', 'sc-tag-tier', tag.tierLabel));
  card.append(el('div', 'sc-tag-label', tag.label));
  card.append(el('div', 'sc-tag-ev', tag.evidence));
  if (tag.roast) card.append(el('div', 'sc-tag-roast', tag.roast));
  return card;
}

/** 组合彩蛋：两张卡碰在一起才成立。这是抽卡真正的那一下。 */
function comboCard(combo) {
  const card = el('div', `sc-combo ${tierClass(combo.tier)}`);
  const head = el('div', 'sc-combo-head');
  head.append(el('span', 'sc-combo-title', combo.title));
  head.append(el('span', 'sc-combo-tier', combo.tierLabel));
  card.append(head);
  card.append(el('div', 'sc-combo-need', combo.need.join(' + ')));
  card.append(el('div', 'sc-combo-blurb', combo.blurb));
  return card;
}

function combosBlock(tags, t) {
  if (!tags.combos?.length) return null;
  const wrap = el('div', 'sc-combos');
  const head = el('div', 'sc-combos-head');
  head.append(el('span', 'sc-combos-title', t.comboTitle));
  head.append(el('span', 'sc-combos-count', t.comboPool(tags.comboPool, tags.combos.length)));
  wrap.append(head);
  const grid = el('div', 'sc-combo-grid');
  for (const c of tags.combos) grid.append(comboCard(c));
  wrap.append(grid);
  return wrap;
}

function tagsBlock(p, t) {
  const tags = p.tags;
  if (!tags) return null;
  const wrap = el('div', 'sc-tags');

  const hero = el('div', 'sc-nick sc-nick-with-avatar');
  hero.append(personalityPortrait(tags));
  const profile = el('div', 'sc-nick-profile');
  profile.append(el('div', 'sc-nick-kicker', t.nickKicker));
  profile.append(el('div', 'sc-nick-name', tags.nickname));
  if (tags.verdict) profile.append(el('div', 'sc-nick-verdict', tags.verdict));
  profile.append(rarityStrip(tags, t));
  hero.append(profile);
  wrap.append(hero);

  if ((tags.tags ?? []).length === 0) {
    wrap.append(el('div', 'sc-prose', t.tagsEmpty));
    return wrap;
  }

  // 组合彩蛋放在标签卡之前：先给「凑出了什么」，再看「构成它的证据」。
  const combos = combosBlock(tags, t);
  if (combos) wrap.append(combos);

  const grid = el('div', 'sc-tag-grid');
  for (const tag of tags.tags) grid.append(tagCard(tag));
  wrap.append(grid);
  return wrap;
}

const PROFILE_ICONS = {
  speech: '<path d="M8 9h24a5 5 0 0 1 5 5v11a5 5 0 0 1-5 5H20l-8 6v-6H8a5 5 0 0 1-5-5V14a5 5 0 0 1 5-5Z" fill="#b6bce9" stroke="#777ebd"/><path d="M11 16h18m-18 5h14m-14 5h8" stroke="#454b80" stroke-linecap="round"/>',
  rhythm: '<path d="M19 5c-7 0-12 6-11 12a11 11 0 0 0 17 8 11 11 0 0 1-6-20Z" fill="#f0d591"/><path d="M29 19h7l5 11H24Z" fill="#e7b878" stroke="#f0d591"/><path d="M32 31v8m-6 0h12" stroke="#b6bce9" stroke-linecap="round"/>',
  emotion: '<path d="M31 21h5a5 5 0 0 1 0 10h-6" fill="none" stroke="#b6bce9" stroke-width="2"/><path d="M8 20h25v8a11 11 0 0 1-11 11h-3A11 11 0 0 1 8 28Z" fill="#b6bce9" stroke="#777ebd"/><path d="M14 42h15M20 17c-8-5 7-7 1-12" fill="none" stroke="#b6bce9" stroke-linecap="round"/>',
  play: '<path d="M6 23c1-8 5-12 11-12h10c6 0 10 4 11 12l2 7c1 4-4 6-7 3l-6-5h-10l-6 5c-3 3-8 1-7-3Z" fill="#a4beeb" stroke="#777ebd"/><path d="M12 21h8m-4-4v8" stroke="#454b80" stroke-linecap="round"/><circle cx="30" cy="19" r="2" fill="#454b80"/><circle cx="34" cy="23" r="2" fill="#454b80"/>',
  memory: '<path d="M9 7h27v24l-8 8H9Z" fill="#e7c58d" stroke="#ab8c67"/><path d="M28 39v-8h8M15 17h15m-15 6h11" fill="none" stroke="#765f4e" stroke-linecap="round"/><circle cx="22" cy="9" r="3" fill="#77cbbd"/>',
};

function profileIcon(id) {
  const image = el('img', 'sc-profile-icon');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 44 44" stroke-width="1.5">${PROFILE_ICONS[id] ?? ''}</svg>`;
  image.setAttribute('src', `data:image/svg+xml,${encodeURIComponent(svg)}`);
  image.setAttribute('alt', '');
  return image;
}

function inviteQuiz(ctx, button, status, t) {
  button.addEventListener('click', async () => {
    button.disabled = true;
    status.textContent = t.starting;
    try {
      const res = await ctx.invoke('startQuiz');
      if (res?.ok) status.textContent = t.started;
      else if (res?.error === 'taken-recently') status.textContent = t.takenRecently;
      else if (res?.error === 'quiz-disabled') status.textContent = t.quizOff;
      else status.textContent = String(res?.error ?? t.failed);
    } catch (err) {
      status.textContent = err?.message ?? t.failed;
    } finally {
      button.disabled = false;
    }
  }, { signal: ctx.signal });
}

function showCardTags(root, tags) {
  root.replaceChildren();
  for (const tag of tags ?? []) root.append(el('span', 'sc-profile-tag', tag));
}

function cardEditor(ctx, panelActions, zh) {
  const box = el('details', 'sc-profile-card sc-profile-editor');
  box.append(el('summary', '', zh ? '用自己的 AI 写名片' : 'Write this card with your AI'));
  const actions = el('div', 'sc-profile-editor-actions');
  const request = el('button', 'sc-btn', zh ? '获取画像提示词' : 'Get the prompt');
  const apply = el('button', 'sc-btn', zh ? '应用 AI 名片' : 'Apply AI card');
  const prompt = el('textarea', 'sc-profile-editor-field');
  prompt.setAttribute('readonly', '');
  prompt.setAttribute('aria-label', zh ? '画像提示词' : 'Profile prompt');
  prompt.rows = 6;
  const result = el('textarea', 'sc-profile-editor-field');
  result.setAttribute('aria-label', zh ? 'AI 返回的 JSON' : 'AI response JSON');
  result.placeholder = zh ? '粘贴 AI 返回的 JSON' : 'Paste the JSON returned by your AI';
  result.rows = 4;
  const status = el('p', 'sc-profile-period');
  status.setAttribute('role', 'status');
  let key = '';
  apply.disabled = true;
  request.addEventListener('click', async () => {
    request.disabled = true;
    try {
      const response = await ctx.invoke('cardPrompt', [ctx.lang]);
      if (!response?.ok) throw new Error('prompt');
      prompt.value = response.prompt;
      key = response.key;
      apply.disabled = false;
      prompt.select();
      status.textContent = zh ? '复制提示词给你的 AI，再把返回的 JSON 粘贴回来。' : 'Copy the prompt to your AI, then paste its JSON response here.';
    } catch {
      status.textContent = zh ? '暂时取不到提示词。' : 'Could not get the prompt.';
    } finally {
      request.disabled = false;
    }
  }, { signal: ctx.signal });
  apply.addEventListener('click', async () => {
    apply.disabled = true;
    try {
      const response = await ctx.invoke('saveProfileCard', [ctx.lang, key,
        result.value.trim().replace(/^\`\`\`(?:json)?\s*|\s*\`\`\`$/gi, '')]);
      if (!response?.ok) {
        status.textContent = response?.error === 'stale'
          ? (zh ? '记录已更新，请重新获取提示词。' : 'Records changed. Get a fresh prompt.')
          : (zh ? '请检查 JSON 格式，以及标签是否在本次可选项内。' : 'Check the JSON format and allowed tags.');
        return;
      }
      await panelActions.load();
    } catch {
      status.textContent = zh ? '暂时没能保存名片。' : 'Could not save the card.';
    } finally {
      apply.disabled = false;
    }
  }, { signal: ctx.signal });
  actions.append(request, apply);
  box.append(actions, prompt, result, status);
  return box;
}

function renderPersona(ctx, report, panelActions) {
  const p = report.personality;
  const profile = p.profile;
  if (!profile) return renderLegacyPersona(ctx, report, panelActions);
  const t = T[ctx.lang];
  const zh = ctx.lang === 'zh';
  const root = el('div', 'sc-root sc-profile');
  const hero = el('section', 'sc-profile-hero');
  const heroText = el('div', 'sc-profile-hero-text');
  if (profile.name) heroText.append(el('div', 'sc-profile-name', profile.name));
  const headline = el('h2', 'sc-profile-title', profile.title);
  headline.setAttribute('data-sc-profile-copy', 'title');
  const label = el('div', 'sc-profile-label', profile.label);
  label.setAttribute('data-sc-profile-copy', 'label');
  heroText.append(label, headline);
  const description = el('p', 'sc-profile-subtitle', profile.description);
  description.setAttribute('data-sc-profile-copy', 'description');
  const tags = el('div', 'sc-profile-tags');
  showCardTags(tags, profile.tags);
  heroText.append(description, tags);
  const portraitFrame = el('div', 'sc-profile-portrait');
  const decor = el('span', 'sc-profile-whale');
  decor.setAttribute('aria-hidden', 'true');
  portraitFrame.append(personalityPortrait(p.tags), decor);
  hero.append(portraitFrame, heroText);
  root.append(hero);

  const columns = el('div', 'sc-profile-columns');
  const analysis = el('section', 'sc-profile-card');
  const analysisHead = el('div', 'sc-profile-head');
  analysisHead.append(el('h3', '', zh ? '性格分析' : 'Personality observations'));
  if (profile.days) analysisHead.append(el('span', 'sc-profile-period', zh ? `近 ${profile.days} 天` : `Last ${profile.days} days`));
  analysis.append(analysisHead);
  const missing = zh ? '近期没有足够的记录。' : 'Not enough recent records.';
  const firstWithEvidence = profile.evidence.find(({ lines }) => lines.length);
  for (const item of profile.evidence) {
    const row = dimRow({
      title: item.title,
      state: item.value == null && !item.lines.length ? 'unknown' : 'ok',
      metricValue: item.value ?? '—',
      hideTrend: true,
      headline: item.summary || '',
      evidence: (item.lines.length ? item.lines : [missing]).map((line, i) => ({
        label: `${i + 1}`, value: line,
      })),
      formula: item.formula ?? missing,
      meaning: item.meaning ?? missing,
    }, t, ctx.lang);
    row.open = item === firstWithEvidence;
    analysis.append(row);
  }
  const recent = el('section', 'sc-profile-card sc-profile-recent');
  recent.append(el('h3', '', zh ? '最近的她' : 'Her lately'));
  if (!profile.recent.length) recent.append(el('p', 'sc-profile-period', missing));
  for (const item of profile.recent) {
    const row = el('div', 'sc-profile-observation');
    const wording = el('div', 'sc-profile-observation-text');
    const sentence = el('p', '', item.summary);
    if (!item.empty && !item.icon) sentence.setAttribute('data-sc-profile-copy', item.id);
    wording.append(el('span', 'sc-profile-period', item.title), sentence);
    row.append(profileIcon(item.icon ?? item.id), wording);
    recent.append(row);
  }
  columns.append(analysis, recent);
  root.append(columns);

  const quiz = el('details', 'sc-profile-card sc-profile-quiz');
  quiz.append(el('summary', '', zh ? '奇遇小测' : 'Curiosity quiz'));
  const quizBody = el('div', 'sc-profile-quiz-body');
  const status = el('div', 'sc-head-note');
  status.setAttribute('role', 'status');
  const button = el('button', 'sc-btn', zh ? '邀请她答题' : 'Invite her to answer');
  quizBody.append(el('p', '', zh ? '遇到这些小情境，她会怎么选？她会在对话里作答。' : 'What would she do in these situations? She answers in the chat.'));
  if (p.takenAt) {
    const when = new Date(p.takenAt).toLocaleDateString(ctx.lang);
    quizBody.append(el('p', 'sc-profile-period', `${t.lastTaken} · ${when}`));
  }
  inviteQuiz(ctx, button, status, t);
  quizBody.append(button, status, creativeCard(ctx, p, t, panelActions));
  quiz.append(quizBody);
  root.append(quiz);
  if (profile.candidates && profile.recent.some((item) => !item.empty)) root.append(cardEditor(ctx, panelActions, zh));
  return root;
}

function renderLegacyPersona(ctx, report, panelActions) {
  const t = T[ctx.lang];
  const p = report.personality;
  const root = el('div', 'sc-root');

  const actions = el('div', 'sc-head-actions');
  const copy = el('button', 'sc-btn sc-btn-ghost', t.copy);
  copy.addEventListener('click', () => void copyReport(ctx, copy, t), { signal: ctx.signal });
  actions.append(copy);
  root.append(actions);

  // 标签永远是首屏第一块——没做测验也有，只是少了几条依赖自述的。
  const block = tagsBlock(p, t);
  if (block) root.append(block);

  root.append(creativeCard(ctx, p, t, panelActions));

  if (!p.taken) {
    const empty = el('div', 'sc-empty');
    empty.append(el('div', 'sc-empty-title', t.notTaken));
    empty.append(el('div', 'sc-prose', t.notTakenHint));
    const btn = el('button', 'sc-btn', t.start);
    const status = el('div', 'sc-head-note', '');
    btn.addEventListener('click', async () => {
      btn.disabled = true;
      status.textContent = t.starting;
      try {
        const res = await ctx.invoke('startQuiz');
        if (res?.ok) status.textContent = t.started;
        else if (res?.error === 'taken-recently') status.textContent = t.takenRecently;
        else if (res?.error === 'quiz-disabled') status.textContent = t.quizOff;
        else status.textContent = String(res?.error ?? t.failed);
      } catch (err) {
        status.textContent = err?.message ?? t.failed;
      } finally {
        btn.disabled = false;
      }
    }, { signal: ctx.signal });
    empty.append(btn, status);
    root.append(empty);
  }

  // 四轴与一致性收进「依据」：还在，可核对，但不再占首屏——
  // 首屏要的是「被认出来」，不是「看分析」。
  const fold = el('details', 'sc-evidence');
  const summary = el('summary', 'sc-evidence-sum');
  summary.append(el('span', 'sc-evidence-k', t.evidenceTitle));
  if (p.taken) summary.append(el('span', 'sc-evidence-v', `${p.letters ?? '—'} · ${t.consistShort} ${p.consistency?.agreeCount ?? 0}/${p.consistency?.total ?? 0}`));
  else summary.append(el('span', 'sc-evidence-v', t.behavOnly));
  fold.append(summary);

  const body = el('div', 'sc-evidence-body');
  if (p.taken) {
    const chart = el('div', 'sc-chart');
    const legend = el('div', 'sc-legend');
    const ls = el('span', 'sc-legend-item');
    ls.append(el('span', 'sc-dot sc-radar-self'));
    ls.append(el('span', '', t.selfP));
    const lb = el('span', 'sc-legend-item');
    lb.append(el('span', 'sc-dot sc-radar-behav'));
    lb.append(el('span', '', t.behav));
    legend.append(ls, lb);
    chart.append(radar({ self: p.selfAxes, behavior: p.behaviorAxes }, t), legend);
    body.append(chart);
    body.append(axisRows(p.selfAxes, p.behaviorAxes, t));
    if (p.consistency?.rows?.length) {
      const box = el('div', 'sc-consist');
      box.append(el('div', 'sc-sect-title', t.consistDetail));
      for (const r of p.consistency.rows) {
        if (!r.text) continue;
        const row = el('div', 'sc-consist-row');
        row.dataset.agree = r.agree === true ? 'yes' : r.agree === false ? 'no' : 'na';
        row.append(el('span', 'sc-consist-k', r.label));
        row.append(el('span', 'sc-consist-v', r.text));
        box.append(row);
      }
      body.append(box);
    }
  } else {
    body.append(el('div', 'sc-label', t.behav));
    body.append(axisRows(null, p.behaviorAxes, t));
  }
  body.append(behaviorNotes(p, t));

  if (p.flags?.length) {
    const box = el('div', 'sc-problems');
    box.append(el('div', 'sc-label', t.flags));
    for (const f of p.flags) {
      const key = f.startsWith('flat') ? 'flagFlat' : f === 'partial' ? 'flagPartial' : f === 'unstable' ? 'flagUnstable' : null;
      box.append(el('div', 'sc-prose', key ? t[key] : f));
    }
    body.append(box);
  }
  fold.append(body);
  root.append(fold);

  root.append(el('div', 'sc-note', t.note));
  root.append(el('div', 'sc-footer', t.footer));
  return root;
}

function behaviorNotes(p, t) {
  const wrap = el('div', 'sc-notes');
  for (const n of p.behaviorNotes || []) {
    const row = el('details', 'sc-note-row');
    row.append(el('summary', 'sc-note-sum', `${n.axis} · ${n.note}`));
    const box = el('div', 'sc-note-body');
    for (const e of n.evidence || []) {
      const line = el('div', 'sc-ev-row');
      line.append(el('span', 'sc-ev-k', e.label));
      line.append(el('span', 'sc-ev-v', String(e.value)));
      if (e.hint) line.append(el('span', 'sc-ev-h', e.hint));
      box.append(line);
    }
    row.append(box);
    wrap.append(row);
  }
  return wrap;
}

/* ------------------------------------------------------------------ 口径 */

function renderMethod(ctx, report) {
  const t = T[ctx.lang];
  const root = el('div', 'sc-root sc-method');
  root.append(el('div', 'sc-prose sc-lead', t.methodIntro));

  root.append(el('h4', 'sc-h', t.methodHw));
  root.append(el('div', 'sc-prose sc-method-principles', t.methodHardwarePrinciples));
  for (const d of report.hardware?.dimensions || []) {
    const block = el('div', 'sc-method-dim');
    block.append(el('div', 'sc-method-title', d.title));
    block.append(el('div', 'sc-prose', d.formula));
    root.append(block);
  }

  const profile = report.personality?.profile;
  if (profile) {
    const zh = ctx.lang === 'zh';
    root.append(el('h4', 'sc-h', zh ? '性格分析与奇遇小测' : 'Observations and curiosity quiz'));
    root.append(el('div', 'sc-prose', zh
      ? '画像取自近期重复出现的观察。接话统计使用影子判断；情绪来自应用内部采样；记忆只统计有效且带日期的条目。奇遇小测单独展示。'
      : 'The profile reflects recurring recent observations. Reply metrics use shadow decisions, emotion metrics use sampled app data, and memory counts include only valid dated entries. The quiz is separate.'));
  } else {
    root.append(el('h4', 'sc-h', t.methodPs));
    root.append(el('div', 'sc-prose', t.methodPsBody));
  }

  // 档位怎么定的：不写会让人以为「少见」是随机贴的
  if (!profile && report.personality?.tags?.pool) {
    root.append(el('h4', 'sc-h', t.methodTiers));
    root.append(el('div', 'sc-prose', t.methodTiersBody));
    const tierList = el('div', 'sc-method-tiers');
    for (const tier of [1, 2, 3, 4]) {
      const row = el('div', `sc-method-tier ${tierClass(tier)}`);
      row.append(el('span', 'sc-method-tier-k', t.tiers[tier]));
      row.append(el('span', 'sc-method-tier-v', t.tierHints[tier]));
      tierList.append(row);
    }
    root.append(tierList);
  }

  root.append(el('h4', 'sc-h', t.sources));
  const list = el('div', 'sc-src');
  for (const [path, what] of SOURCES) {
    const row = el('div', 'sc-src-row');
    row.append(el('code', 'sc-src-path', path));
    row.append(el('span', 'sc-src-what', what));
    list.append(row);
  }
  root.append(list);

  root.append(el('h4', 'sc-h', t.notDo));
  root.append(el('div', 'sc-prose', t.notDoBody));
  root.append(el('div', 'sc-footer', t.footer));
  return root;
}

/* ------------------------------------------------------------------ 公共 */

async function copyReport(ctx, btn, t) {
  try {
    const res = await ctx.invoke('text');
    const text = typeof res?.text === 'string' ? res.text : '';
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
    const prev = btn.textContent;
    btn.textContent = t.copied;
    ctx.timeout(() => { btn.textContent = prev; }, 1500);
  } catch (err) {
    btn.textContent = err?.message ?? t.failed;
  }
}

function makePanel(render) {
  return {
    async mount(ctx) {
      ctx.lang = String(ctx.language ?? 'zh').toLowerCase().startsWith('zh') ? 'zh' : 'en';
      ctx.root.classList.add('sc-panel');
      const holder = el('div', 'sc-holder');
      ctx.root.append(holder);
      const state = { report: null };

      const paint = () => {
        const t = T[ctx.lang];
        holder.replaceChildren();
        if (!state.report) {
          holder.append(el('div', 'sc-prose', t.loading));
          return;
        }
        holder.append(render(ctx, state.report, { load, refresh }));
      };

      async function load() {
        const t = T[ctx.lang];
        try {
          const res = await ctx.invoke('report', [ctx.lang]);
          if (res?.ok && res.report) {
            state.report = res.report;
            paint();
            if (render === renderPersona && res.report.personality?.profile?.canGenerate) {
              void applyProfileCopy(res.report);
            }
            return;
          }
          holder.replaceChildren(el('div', 'sc-prose', `${t.failed}: ${res?.error ?? ''}`));
        } catch (err) {
          holder.replaceChildren(el('div', 'sc-prose', `${t.failed}: ${err?.message ?? err}`));
        }
      }

      async function applyProfileCopy(report) {
        const key = JSON.stringify(report.personality.profile.recent.filter((row) => !row.empty).map(({ id, summary }) => [id, summary]));
        try {
          const res = await ctx.invoke('profileCopy', [ctx.lang, key]);
          if (state.report !== report || ctx.signal?.aborted || !res?.copy) return;
          const { title, recent, label, description, tags } = res.copy;
          const fields = { ...recent, title, label, description };
          const tagRoot = holder.querySelector('.sc-profile-tags');
          if (tagRoot && tags) showCardTags(tagRoot, tags);
          for (const item of holder.querySelectorAll('[data-sc-profile-copy]')) {
            const id = item.getAttribute('data-sc-profile-copy');
            const copy = fields[id];
            if (copy) item.textContent = copy;
          }
        } catch { /* Keep the local report if the host cannot generate copy. */ }
      }

      async function refresh() {
        try {
          await ctx.invoke('refresh', []);
        } catch { /* 刷新失败就直接重读，下面还会兜一轮 */ }
        await load();
      }

      paint();
      await load();
    },
  };
}

export default {
  panels: {
    hardware: makePanel(renderHardware),
    persona: makePanel(renderPersona),
    method: makePanel(renderMethod),
  },
};
